/* Emphasis follows the task, not DOM position. */
.primary { font-weight: 600; color: #221c24; }
.supporting { font-weight: 400; color: #6f6470; }
.actions { display: flex; flex-wrap: wrap; gap: .75rem; }

.choice { transition: background-color 120ms ease-out; }
.choice[aria-pressed="true"] { background: #efeaee; }
@media (prefers-reduced-motion: reduce) {
  .choice { transition: none; }
}
/* Never delay state updates until animation completes. */

.grid { display: grid; gap: 1.5rem;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr)); }
.grid > * { min-width: 0; overflow-wrap: anywhere; }
button, input, select { min-height: 44px; }
